package main

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"golang.org/x/term"
)

// The official Intropy skills collection offered by `int create`.
const (
	defaultSkillsCollectionAlias = "intropy"
	defaultSkillsCollectionRef   = "harbor.intropy.io/skills/index:latest"
)

// skillsCollectionRef returns the collection to offer, overridable via
// INTROPY_SKILLS_COLLECTION (useful for testing against a local registry).
func skillsCollectionRef() string {
	return cmp.Or(os.Getenv("INTROPY_SKILLS_COLLECTION"), defaultSkillsCollectionRef)
}

// decideInstallSkills is the pure gating logic for the post-scaffold skills
// install: --skip-install-skills forces a no and --install-skills forces a
// yes, both without prompting; otherwise --no-input and non-terminal stdin
// skip, and an interactive session gets a [Y/n] prompt (default yes).
func decideInstallSkills(force, skip, noInput bool, in io.Reader, errW io.Writer) (bool, error) {
	if skip {
		return false, nil
	}
	if force {
		return true, nil
	}
	if noInput {
		return false, nil
	}
	f, ok := in.(*os.File)
	if !ok || !term.IsTerminal(int(f.Fd())) {
		return false, nil
	}
	return confirmInstallSkills(in, errW)
}

// maybeInstallSkills applies decideInstallSkills and, on yes, does the
// equivalent of `skills collection add` plus `skills add` for every skill in
// the collection. On no, it prints how to install later — unless the skip
// was the explicit --skip-install-skills, where a hint would just be noise.
func maybeInstallSkills(ctx context.Context, in io.Reader, errW io.Writer, force, skip, noInput bool, outputDir string) error {
	install, err := decideInstallSkills(force, skip, noInput, in, errW)
	if err != nil {
		return err
	}
	ref := skillsCollectionRef()
	if !install {
		if !skip {
			fmt.Fprintf(errW, "skills not installed — run 'intropy skills collection add --name %s --ref %s' in the integration later\n",
				defaultSkillsCollectionAlias, ref)
		}
		return nil
	}

	project, err := skillProjectAt(outputDir)
	if err != nil {
		return err
	}
	client, err := newSkillRegistry()
	if err != nil {
		return err
	}
	installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
	adder := skill.NewAdder(client, installer, project)

	entries, err := skill.NewCollectionInstaller(client, adder, project).
		InstallAll(ctx, defaultSkillsCollectionAlias, ref)
	if err != nil {
		return err
	}
	for _, e := range entries {
		fmt.Fprintf(errW, "  installed %s @ %s -> %s\n", e.Name, e.Source.Tag, e.Path)
	}
	fmt.Fprintf(errW, "installed %d skill(s) from %s\n", len(entries), ref)
	return nil
}

// confirmInstallSkills renders a [Y/n] prompt (default yes) and reads the
// answer. EOF counts as a decline, not an error.
func confirmInstallSkills(in io.Reader, out io.Writer) (bool, error) {
	v, err := template.NewStdinPrompter(in, out).Prompt(template.FieldSpec{
		Name:    "install-skills",
		Title:   "Install agent skills into .agents/skills?",
		Type:    "boolean",
		Default: true,
	})
	if errors.Is(err, io.EOF) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	b, ok := v.(bool)
	return ok && b, nil
}

// skillProjectAt returns the skills project rooted exactly at dir, creating an
// empty skills.json there if the template didn't ship one. Unlike
// resolveOrBootstrapProject it never walks up: the scaffolded integration is
// its own skills project even when created inside a larger repo.
func skillProjectAt(dir string) (*skill.Project, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, err
	}
	p := &skill.Project{Root: abs}
	if _, err := os.Stat(p.ManifestPath()); err == nil {
		return p, nil
	} else if !os.IsNotExist(err) {
		return nil, err
	}
	if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
		return nil, fmt.Errorf("bootstrap skills.json: %w", err)
	}
	return p, nil
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/spf13/cobra"
)

type skillsAddFlags struct {
	additionalBasePaths []string
	name                string
	collection          string
	output              string
}

var skillsAddOpts skillsAddFlags

var skillsAddCmd = &cobra.Command{
	Use:   "add [ref]",
	Short: "Add a skill to the project and install it",
	Long: `Adds a skill to skills.json, pulls it from the OCI registry, and
extracts it under .agents/skills/<name>/.

Either pass a full OCI ref as a positional argument (e.g.
ghcr.io/example/skills/pr-review:1.0.0) or pass --name <skill-name> to
resolve the ref from a registered collection. Use --collection to
disambiguate when the same name appears in multiple collections.

If no skills.json exists in the current directory or any parent, an empty one
is created in the current directory.`,
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(skillsAddOpts.output, "json", "plain"); err != nil {
			return err
		}
		if len(args) == 0 && skillsAddOpts.name == "" {
			return newUsageErrorf("requires either a ref argument or --name")
		}
		if len(args) == 1 && skillsAddOpts.name != "" {
			return newUsageErrorf("pass either a ref argument or --name, not both")
		}
		if len(args) == 0 && skillsAddOpts.collection != "" && skillsAddOpts.name == "" {
			return newUsageErrorf("--collection only applies with --name")
		}

		project, err := resolveOrBootstrapProject(".")
		if err != nil {
			return fmt.Errorf("add: %w", err)
		}

		ref := ""
		if len(args) == 1 {
			ref = args[0]
		} else {
			resolution, err := skill.ResolveSkillName(project, skillsAddOpts.name, skillsAddOpts.collection)
			if err != nil {
				return fmt.Errorf("add: %w", err)
			}
			ref = resolution.Entry.Ref
			if ref == "" {
				return fmt.Errorf("add: collection entry for %q has no ref annotation", skillsAddOpts.name)
			}
		}

		client, err := newSkillRegistry()
		if err != nil {
			return fmt.Errorf("add: %w", err)
		}

		installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
		adder := skill.NewAdder(client, installer, project)

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		entry, err := adder.Add(ctx, ref, skill.AddOptions{
			AdditionalBasePaths: skillsAddOpts.additionalBasePaths,
		})
		if err != nil {
			return fmt.Errorf("add: %w", err)
		}

		if skillsAddOpts.output == "json" {
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entry)
		}
		fmt.Fprintf(cmd.ErrOrStderr(), "Added %s @ %s\n", entry.Name, entry.Source.Tag)
		fmt.Fprintf(cmd.ErrOrStderr(), "  digest: %s\n", entry.Source.Digest)
		fmt.Fprintf(cmd.ErrOrStderr(), "  path:   %s\n", entry.Path)
		return nil
	},
}

// resolveOrBootstrapProject locates a skills.json by walking up from startDir;
// if none is found, it creates an empty one in startDir and returns the
// resulting Project. This inlines the only piece of the unported `init`
// command that `add` needs.
func resolveOrBootstrapProject(startDir string) (*skill.Project, error) {
	project, err := skill.FindProject(startDir)
	if err == nil {
		return project, nil
	}
	if !errors.Is(err, skill.ErrProjectNotFound) {
		return nil, err
	}

	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, err
	}
	p := &skill.Project{Root: abs}
	if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
		return nil, fmt.Errorf("bootstrap skills.json: %w", err)
	}
	return p, nil
}

func init() {
	skillsAddCmd.Flags().StringSliceVar(
		&skillsAddOpts.additionalBasePaths,
		"also-install-to", nil,
		"Additional directories to install the skill into (can be repeated)",
	)
	skillsAddCmd.Flags().StringVar(
		&skillsAddOpts.name,
		"name", "",
		"Install a skill by name from a registered collection",
	)
	skillsAddCmd.Flags().StringVar(
		&skillsAddOpts.collection,
		"collection", "",
		"Restrict --name lookup to a single registered collection",
	)
	skillsAddCmd.Flags().StringVarP(&skillsAddOpts.output, "output", "o", "plain", "output format: plain or json")
	_ = skillsAddCmd.RegisterFlagCompletionFunc("collection", completeRegisteredCollections)
	skillsCmd.AddCommand(skillsAddCmd)
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/spf13/cobra"
)

type skillsListFlags struct {
	output string
}

var skillsListOpts skillsListFlags

var skillsListCmd = &cobra.Command{
	Use:   "list",
	Short: "List installed skills",
	Args:  cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(skillsListOpts.output, "json", "plain"); err != nil {
			return err
		}

		project, err := skill.FindProject(".")
		if err != nil {
			if errors.Is(err, skill.ErrProjectNotFound) {
				fmt.Fprintln(cmd.ErrOrStderr(), "No skills installed.")
				return nil
			}
			return fmt.Errorf("list: %w", err)
		}

		lockfile, err := project.LoadLockfile()
		if err != nil {
			return fmt.Errorf("list: load lockfile: %w", err)
		}

		if len(lockfile.Skills) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "No skills installed.")
			fmt.Fprintln(cmd.ErrOrStderr(), "Use `intropy skills add <ref>` to add one.")
			return nil
		}

		if skillsListOpts.output == "json" {
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(lockfile.Skills)
		}

		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "NAME\tVERSION\tDIGEST\tPATH")
		for _, s := range lockfile.Skills {
			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\n",
				s.Name,
				s.Source.Tag,
				shortDigest(s.Source.Digest),
				s.Path,
			)
		}
		return tw.Flush()
	},
}

// shortDigest abbreviates "sha256:abc123..." to "sha256:abc123" (12 chars after prefix).
// Full digests are 71 chars and dominate the table; the prefix is enough to identify.
func shortDigest(d string) string {
	const prefix = "sha256:"
	if len(d) <= len(prefix)+12 {
		return d
	}
	return d[:len(prefix)+12]
}

func init() {
	f := skillsListCmd.Flags()
	f.StringVarP(&skillsListOpts.output, "output", "o", "plain", "output format: plain or json")
	skillsCmd.AddCommand(skillsListCmd)
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/spf13/cobra"
)

type skillsUpdateFlags struct {
	all    bool
	output string
}

var skillsUpdateOpts skillsUpdateFlags

var skillsUpdateCmd = &cobra.Command{
	Use:   "update [name]",
	Short: "Update an installed skill to the version pinned by its collection",
	Long: `Reconciles an installed skill against the ref currently pinned by the
registered collections (as seen in the local index cache). If the resolved
ref differs from what's in skills.json, the new content is pulled and
.agents/skills/<name> is replaced.

Run 'intropy skills collection update <alias>' first to refresh the cache if
the upstream collection has been republished.

Pass --all to reconcile every installed skill at once.`,
	Args:              cobra.MaximumNArgs(1),
	ValidArgsFunction: completeInstalledSkills,
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(skillsUpdateOpts.output, "json", "plain"); err != nil {
			return err
		}
		if len(args) == 0 && !skillsUpdateOpts.all {
			return newUsageErrorf("requires a skill name or --all")
		}
		if len(args) == 1 && skillsUpdateOpts.all {
			return newUsageErrorf("pass either a skill name or --all, not both")
		}

		project, err := skill.FindProject(".")
		if err != nil {
			return fmt.Errorf("update: %w", err)
		}

		client, err := newSkillRegistry()
		if err != nil {
			return fmt.Errorf("update: %w", err)
		}

		installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
		updater := skill.NewUpdater(client, installer, project)

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		var names []string
		if skillsUpdateOpts.all {
			manifest, err := project.LoadManifest()
			if err != nil {
				return fmt.Errorf("update: %w", err)
			}
			if len(manifest.Skills) == 0 {
				fmt.Fprintln(cmd.ErrOrStderr(), "No skills installed.")
				return nil
			}
			for _, e := range manifest.Skills {
				names = append(names, e.Name)
			}
		} else {
			names = []string{args[0]}
		}

		var results []skill.UpdateResult
		for _, name := range names {
			result, err := updater.Update(ctx, name)
			if err != nil {
				return fmt.Errorf("update: %w", err)
			}
			results = append(results, result)
			if skillsUpdateOpts.output == "plain" {
				if result.Changed {
					fmt.Fprintf(cmd.ErrOrStderr(), "Updated %s: %s -> %s\n", name, result.OldVersion, result.NewVersion)
				} else {
					fmt.Fprintf(cmd.ErrOrStderr(), "%s already at %s\n", name, result.OldVersion)
				}
			}
		}

		if skillsUpdateOpts.output == "json" {
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(results)
		}

		changed := 0
		for _, r := range results {
			if r.Changed {
				changed++
			}
		}
		if changed == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "Nothing to update.")
		}

		return nil
	},
}

func init() {
	skillsUpdateCmd.Flags().BoolVar(
		&skillsUpdateOpts.all, "all", false,
		"Update every installed skill",
	)
	skillsUpdateCmd.Flags().StringVarP(&skillsUpdateOpts.output, "output", "o", "plain", "output format: plain or json")
	skillsCmd.AddCommand(skillsUpdateCmd)
}

