package main

import (
	"fmt"

	"github.com/spf13/cobra"
)

// registerTemplateVersionFlag wires --template-version (canonical) and its
// deprecated alias --version onto cmd. The alias exists because --version
// named the template release before the CLI grew a release command where
// --version means the version being published — one flag name, two
// meanings. resolveTemplateVersion folds the alias into the value and
// warns; it must be called from the command's RunE.
//
// Usage strings are identical on both flags so help output stays truthful
// whichever one a user reads.
func registerTemplateVersionFlag(cmd *cobra.Command, target *string) {
	f := cmd.Flags()
	f.StringVar(target, "template-version", "", "template release tag (default: latest)")
	f.StringVar(&templateVersionAlias{target}.value, "version", "", "template release tag (default: latest) (deprecated: use --template-version)")
	_ = f.MarkHidden("version")
}

// templateVersionAlias binds the deprecated --version flag without giving it
// its own storage: writing --version writes through to the same variable as
// --template-version, and Changed detection tells the two apart in
// resolveTemplateVersion. The intermediate type exists because a
// pflag.Value cannot share a *string through StringVar directly.
type templateVersionAlias struct {
	target *string
}

func (a templateVersionAlias) value() string { return *a.target }

// resolveTemplateVersion merges the deprecated --version alias into the
// canonical --template-version value. Both set is a usage error; only the
// alias set warns on stderr and copies.
func resolveTemplateVersion(cmd *cobra.Command, target *string) error {
	f := cmd.Flags()
	canonical := f.Lookup("template-version")
	alias := f.Lookup("version")
	if canonical == nil || alias == nil {
		return nil
	}
	aliasSet := f.Changed("version")
	canonicalSet := f.Changed("template-version")
	switch {
	case aliasSet && canonicalSet:
		if alias.Value.String() != canonical.Value.String() {
			return newUsageErrorf("cannot combine --version with --template-version (they are the same flag; --version is deprecated)")
		}
		// Same value via both spellings is harmless; warn and continue.
		fallthrough
	case aliasSet:
		fmt.Fprintln(cmd.ErrOrStderr(), "warning: --version is deprecated; use --template-version (elsewhere --version prints the CLI's own version or names a release to publish)")
		*target = alias.Value.String()
	}
	return nil
}

